CREATE TYPE public.fuel_role AS ENUM ('fuel_rider','fuel_station');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.fuel_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY fuel_own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_fuel_role(r public.fuel_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role=r) $$;
CREATE TABLE public.fuel_accounts (user_id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES public.companies(id), motoboy_id uuid REFERENCES public.motoboys(id), username text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(motoboy_id));
GRANT SELECT ON public.fuel_accounts TO authenticated; GRANT ALL ON public.fuel_accounts TO service_role;
ALTER TABLE public.fuel_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY fuel_accounts_read ON public.fuel_accounts FOR SELECT TO authenticated USING(user_id=auth.uid() OR (company_id=public.get_user_company_id() AND public.get_user_role()='admin'));
CREATE FUNCTION public.fuel_company() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE((SELECT company_id FROM public.fuel_accounts WHERE user_id=auth.uid()),public.get_user_company_id()) $$;
CREATE FUNCTION public.fuel_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE(public.get_user_role()='admin',false) AND NOT EXISTS(SELECT 1 FROM public.fuel_accounts WHERE user_id=auth.uid()) $$;
CREATE TABLE public.fuel_prices (company_id uuid PRIMARY KEY REFERENCES public.companies(id), price numeric(10,3) NOT NULL CHECK(price>0 AND price<=100), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.fuel_prices TO authenticated; GRANT ALL ON public.fuel_prices TO service_role;
ALTER TABLE public.fuel_prices ENABLE ROW LEVEL SECURITY;
CREATE POLICY fuel_prices_read ON public.fuel_prices FOR SELECT TO authenticated USING(company_id=public.fuel_company() AND (public.fuel_admin() OR public.has_fuel_role('fuel_rider') OR public.has_fuel_role('fuel_station')));
CREATE POLICY fuel_prices_insert ON public.fuel_prices FOR INSERT TO authenticated WITH CHECK(company_id=public.fuel_company() AND (public.fuel_admin() OR public.has_fuel_role('fuel_station')));
CREATE POLICY fuel_prices_update ON public.fuel_prices FOR UPDATE TO authenticated USING(company_id=public.fuel_company() AND (public.fuel_admin() OR public.has_fuel_role('fuel_station'))) WITH CHECK(company_id=public.fuel_company() AND (public.fuel_admin() OR public.has_fuel_role('fuel_station')));
CREATE TABLE public.fuel_fillings (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES public.companies(id), user_id uuid NOT NULL, motoboy_id uuid NOT NULL, motoboy_name text NOT NULL DEFAULT '', motoboy_code text, plate text, amount numeric(12,2) NOT NULL CHECK(amount>0 AND amount<=100000), discount numeric(12,2) NOT NULL DEFAULT 0 CHECK(discount>=0 AND discount<amount), price numeric(10,3) NOT NULL DEFAULT 1, liters numeric(14,4) NOT NULL DEFAULT 0, receipt_path text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.fuel_fillings TO authenticated; GRANT ALL ON public.fuel_fillings TO service_role;
ALTER TABLE public.fuel_fillings ENABLE ROW LEVEL SECURITY;
CREATE POLICY fuel_fillings_read ON public.fuel_fillings FOR SELECT TO authenticated USING(company_id=public.fuel_company() AND (public.fuel_admin() OR public.has_fuel_role('fuel_station') OR (user_id=auth.uid() AND public.has_fuel_role('fuel_rider'))));
CREATE POLICY fuel_fillings_insert ON public.fuel_fillings FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND company_id=public.fuel_company() AND public.has_fuel_role('fuel_rider'));
CREATE FUNCTION public.validate_fuel_filling() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.fuel_accounts; m public.motoboys; p numeric; BEGIN
SELECT * INTO a FROM public.fuel_accounts WHERE user_id=auth.uid();
IF a.user_id IS NULL OR NOT public.has_fuel_role('fuel_rider') THEN RAISE EXCEPTION 'Acesso negado'; END IF;
SELECT * INTO m FROM public.motoboys WHERE id=a.motoboy_id AND company_id=a.company_id;
IF m.id IS NULL THEN RAISE EXCEPTION 'Cadastro não encontrado'; END IF;
SELECT price INTO p FROM public.fuel_prices WHERE company_id=a.company_id FOR SHARE;
IF p IS NULL THEN RAISE EXCEPTION 'O posto precisa configurar o preço do litro'; END IF;
IF NEW.receipt_path NOT LIKE auth.uid()::text || '/' || NEW.id::text || '.%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='fuel-receipts' AND name=NEW.receipt_path) THEN RAISE EXCEPTION 'Comprovante não encontrado'; END IF;
NEW.company_id:=a.company_id; NEW.user_id:=auth.uid(); NEW.motoboy_id:=m.id; NEW.motoboy_name:=m.name; NEW.motoboy_code:=m.number; NEW.plate:=m.plate; NEW.price:=p; NEW.liters:=round((NEW.amount-NEW.discount)/p,4); NEW.created_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER fuel_filling_validation BEFORE INSERT ON public.fuel_fillings FOR EACH ROW EXECUTE FUNCTION public.validate_fuel_filling();
CREATE POLICY fuel_receipt_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='fuel-receipts' AND (storage.foldername(name))[1]=auth.uid()::text AND public.has_fuel_role('fuel_rider'));
CREATE POLICY fuel_receipt_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='fuel-receipts' AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.fuel_fillings f WHERE f.receipt_path=name AND f.company_id=public.fuel_company() AND (public.fuel_admin() OR public.has_fuel_role('fuel_station')))));
CREATE FUNCTION public.fuel_rider_details() RETURNS TABLE(id uuid,name text,number text,plate text,status public.status_type,payment_status text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT m.id,m.name,m.number,m.plate,m.status,m.payment_status FROM public.motoboys m JOIN public.fuel_accounts a ON a.motoboy_id=m.id AND a.company_id=m.company_id WHERE a.user_id=auth.uid() AND public.has_fuel_role('fuel_rider') $$;
REVOKE ALL ON FUNCTION public.fuel_rider_details() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.fuel_rider_details() TO authenticated;
CREATE INDEX fuel_fillings_company_date ON public.fuel_fillings(company_id,created_at DESC);